def create_trade_source(sids, trade_time_increment, sim_params, concurrent=False):
    if trading.environment.is_market_hours(sim_params.period_end):
        end = sim_params.period_end
    else:
        end = sim_params.last_close
    args = tuple()
    kwargs = {'sids': sids, 'start': sim_params.first_open, 'end': end, 'delta': trade_time_increment, 'filter': sids, 'concurrent': concurrent}
    source = SpecificEquityTrades(*args, **kwargs)
    return source

