def find_templates(self, name=None, include_public=False, public_projects=None, filter_expr=None, order_by=None, max_results=None):
    if name:
        filter_expr = f'name={name}'
    elif not filter_expr:
        raise ValueError("Either 'name' or 'filter_expr' must be specified")
    return self._list_templates(filter_expr=filter_expr, include_public=include_public, public_projects=public_projects, order_by=order_by, max_results=max_results)

