def get_subnet_id_for_vpc(ec2_client: botocore.client.BaseClient, vpc_id: str) -> Optional[str]:
    subnets = _get_subnets_by_vpc_id(ec2_client=ec2_client, vpc_id=vpc_id)
    if len(subnets) == 0:
        return None
    for subnet in subnets:
        subnet_id = subnet['SubnetId']
        if _is_public_subnet(ec2_client=ec2_client, subnet_id=subnet_id):
            return subnet_id
    return None

