def check_config_option_in_central_place(logical_line, filename):
    msg = "N342: Config options should be in the central location '/nova/conf/*'. Do not declare new config options outside of that folder."
    if 'nova/conf/' in filename:
        return
    conf_exceptions = ['nova/cmd/manage.py', 'nova/cmd/policy_check.py', 'nova/tests']
    if any((f in filename for f in conf_exceptions)):
        return
    if cfg_opt_re.match(logical_line):
        yield (0, msg)

