def get_first_applied_membership_fee() -> MembershipFee:
    """Get the first applied membership fee."""
    # TODO use `select` API
    return typing.cast(
        MembershipFee,
        MembershipFee.q.order_by(MembershipFee.ends_on.desc()).first()
    )

