def _mpl_linestyle2pgfp_linestyle(line_style):
    show_line = line_style != 'None'
    try:
        style = MPLLINESTYLE_2_PGFPLOTSLINESTYLE[line_style]
    except KeyError:
        print('Unknown line style %r. Using default.' % line_style)
        style = None
    return (show_line, style)

