def check_parameters_default_constructible(name, Estimator):
    Estimator = Estimator.__class__
    with ignore_warnings(category=FutureWarning):
        estimator = _construct_instance(Estimator)
        clone(estimator)
        repr(estimator)
        assert estimator.set_params() is estimator
        init = getattr(estimator.__init__, 'deprecated_original', estimator.__init__)
        try:

            def param_filter(p):
                return p.name != 'self' and p.kind != p.VAR_KEYWORD and (p.kind != p.VAR_POSITIONAL)
            init_params = [p for p in signature(init).parameters.values() if param_filter(p)]
        except (TypeError, ValueError):
            return
        params = estimator.get_params()
        init_params = init_params[len(getattr(estimator, '_required_parameters', [])):]
        for init_param in init_params:
            assert init_param.default != init_param.empty, 'parameter %s for %s has no default value' % (init_param.name, type(estimator).__name__)
            if type(init_param.default) is type:
                assert init_param.default in [np.float64, np.int64]
            else:
                assert type(init_param.default) in [str, int, float, bool, tuple, type(None), np.float64, types.FunctionType, joblib.Memory]
            if init_param.name not in params.keys():
                assert init_param.default is None
                continue
            param_value = params[init_param.name]
            if isinstance(param_value, np.ndarray):
                assert_array_equal(param_value, init_param.default)
            elif is_scalar_nan(param_value):
                assert param_value is init_param.default, init_param.name
            else:
                assert param_value == init_param.default, init_param.name

