    if configuration_helpers is None:
        raise NotConnectedToOpenEdX(_('This package must be installed in an EdX environment to look up configuration.'))
    return urljoin(configuration_helpers.get_value('LMS_ROOT_URL', settings.LMS_ROOT_URL), reverse('enterprise_program_enrollment_page', kwargs={'enterprise_uuid': self.uuid, 'program_uuid': program_uuid}))

