def submission(request, username=None):
    if username and username.lower() != 'crowdforms':
        formlist_user = get_object_or_404(User, username=username.lower())
        profile, created =\
            UserProfile.objects.get_or_create(user=formlist_user)
        if profile.require_auth:
            authenticator = HttpDigestAuthenticator()
            if not authenticator.authenticate(request):
                return authenticator.build_challenge_response()
    if request.method == 'HEAD':
        response = OpenRosaResponse(status=204)
        if username:
            response['Location'] = request.build_absolute_uri().replace(
                request.get_full_path(), '/%s/submission' % username)
        else:
            response['Location'] = request.build_absolute_uri().replace(
                request.get_full_path(), '/submission')
        return response
    context = RequestContext(request)
    xml_file_list = []
    media_files = []
    html_response = False
    try:
        xml_file_list = request.FILES.pop("xml_submission_file", [])
        if len(xml_file_list) != 1:
            return OpenRosaResponseBadRequest(
                _(u"There should be a single XML submission file.")
            )
        media_files = request.FILES.values()
        uuid = request.POST.get('uuid')
        if not username and uuid:
            html_response = True
        try:
            instance = create_instance(
                username,
                xml_file_list[0],
                media_files,
                uuid=uuid, request=request
            )
        except InstanceInvalidUserError:
            return OpenRosaResponseBadRequest(_(u"Username or ID required."))
        except IsNotCrowdformError:
            return OpenRosaResponseNotAllowed(
                _(u"Sorry but the crowd form you submitted to is closed.")
            )
        except InstanceEmptyError:
            return OpenRosaResponseBadRequest(
                _(u"Received empty submission. No instance was created")
            )
        except FormInactiveError:
            return OpenRosaResponseNotAllowed(_(u"Form is not active"))
        except XForm.DoesNotExist:
            return OpenRosaResponseNotFound(
                _(u"Form does not exist on this account")
            )
        except ExpatError:
            return OpenRosaResponseBadRequest(_(u"Improperly formatted XML."))
        except DuplicateInstance:
            response = OpenRosaResponse(_(u"Duplicate submission"))
            response.status_code = 202
            response['Location'] = request.build_absolute_uri(request.path)
            return response
        except PermissionDenied, e:
            return OpenRosaResponseNotAllowed(e.message)
        except Exception, e:
            raise
        if instance is None:
            return OpenRosaResponseBadRequest(
                _(u"Unable to create submission."))
        audit = {
            "xform": instance.xform.id_string
        }
        audit_log(
            Actions.SUBMISSION_CREATED, request.user, instance.xform.user,
            _("Created submission on form %(id_string)s.") %
            {
                "id_string": instance.xform.id_string
            }, audit, request)
        if html_response:
            context.username = instance.user.username
            context.id_string = instance.xform.id_string
            context.domain = Site.objects.get(id=settings.SITE_ID).domain
            response = render_to_response("submission.html",
                                          context_instance=context)
        else:
            context.message = _("Successful submission.")
            context.formid = instance.xform.id_string
            context.encrypted = instance.xform.encrypted
            context.instanceID = u'uuid:%s' % instance.uuid
            context.submissionDate = instance.date_created.isoformat()
            context.markedAsCompleteDate = instance.date_modified.isoformat()
            t = loader.get_template('submission.xml')
            response = BaseOpenRosaResponse(t.render(context))
        response.status_code = 201
        response['Location'] = request.build_absolute_uri(request.path)
        return response
    except IOError as e:
        if 'request data read error' in unicode(e):
            return OpenRosaResponseBadRequest(
                _(u"File transfer interruption."))
        else:
            raise
    finally:
        if len(xml_file_list):
            [_file.close() for _file in xml_file_list]
        if len(media_files):
            [_file.close() for _file in media_files]

def updateAllTabs(self):
    self.Freeze()
    todo = []
    todo.append((self.name, self.playlist.name))
    if self.playlist.description:
        todo.append((self.description, self.playlist.description))
    todo.append((self.torrents, str(self.playlist.nr_torrents)))
    for (control, new_value) in todo:
        if control.GetLabel() != new_value:
            control.SetLabel(new_value)
    self.description.Show(bool(self.playlist.description))
    self.description_title.Show(bool(self.playlist.description))
    self.bigthumb.SetBitmaps([])
    for sbmp in self.smallthumbs:
        sbmp.SetBitmap(wx.NullBitmap)
    if self.playlist and self.playlist.nr_torrents > 0:
        if self.playlist_torrents is None:

            def do_db():
                return ChannelManager.getInstance().getTorrentsFromPlaylist(self.playlist)[2]

            def do_gui(delayedResult):
                self.playlist_torrents = delayedResult.get()
                bmps = []
                for torrent in self.playlist_torrents:
                    if torrent.metadata:
                        thumbnail_data = self.guiutility.utility.session.get_thumbnail_data(torrent.metadata['thumb_hash'])
                        img = wx.EmptyImage()
                        img.LoadStream(StringIO(thumbnail_data))
                        bitmap = wx.BitmapFromImage(img)
                        bmps.append(bitmap)
                    if len(bmps) > 3:
                        break
                if bmps:
                    self.thumbnails.Show(True)
                    self.Freeze()
                    res_large = limit_resolution(bmps[0].GetSize(), (175, 175))
                    res_small = limit_resolution(bmps[0].GetSize(), (85, 85))
                    bmps_large = [bmp.ConvertToImage().Scale(*res_large, quality=wx.IMAGE_QUALITY_HIGH).ConvertToBitmap() for bmp in bmps if bmp.IsOk()]
                    bmps_small = [bmp.ConvertToImage().Scale(*res_small, quality=wx.IMAGE_QUALITY_HIGH).ConvertToBitmap() for bmp in bmps if bmp.IsOk()]
                    self.bigthumb.SetBitmaps(bmps_large)
                    for (i, sbmp) in enumerate(self.smallthumbs):
                        if i < len(bmps_small):
                            sbmp.SetBitmap(bmps_small[i])
                    self.thumbnails.Layout()
                    self.detailsTab.Layout()
                    self.Thaw()
            startWorker(do_gui, do_db, retryOnBusy=True, priority=GUI_PRI_DISPERSY)
    self.detailsTab.Layout()
    self.Thaw()

