def _populate_scores_dict(self, bss_output):
    (sdr_list, isr_list, sir_list, sar_list, perm) = bss_output
    self.scores[self.RAW_VALUES] = {self.SDR: sdr_list, self.ISR: isr_list, self.SIR: sir_list, self.SAR: sar_list, self.PERMUTATION: perm}
    idx = 0
    for (i, label) in enumerate(self.source_labels):
        self.scores[label] = {}
