def clone(self, clone_name):
    clone_id = self.id + '_CLONED.' + clone_name
    if clone_id in [card_type.id for card_type in self.card_types()]:
        raise NameError
    C = type(mangle(clone_name), (self.__class__,), {'name': clone_name, 'is_clone': True, 'id': clone_id})
    self.component_manager.register(C(self.component_manager))

def run_simple_pex(pex, args=(), interpreter=None, stdin=None, **kwargs):
    p = PEX(pex, interpreter=vendor.setup_interpreter(interpreter))
    process = p.run(args=args, blocking=False, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, **kwargs)
    (stdout, _) = process.communicate(input=stdin)
    print(stdout.decode('utf-8') if PY3 else stdout)
    return (stdout.replace(b'\r', b''), process.returncode)

