def __setitem__(self, item: Union[slice, str], value):
    if isinstance(item, str):
        if isinstance(value, np.ndarray):
            write_array(value, item, storage=self.provider, batched=True)
            ds_meta = read_dataset_meta(self.provider)
            ds_meta['tensors'].append(item)
            write_dataset_meta(self.provider, ds_meta)
            self.tensors[item] = Tensor(item, self.provider)
            return self.tensors[item]
        else:
            raise UnsupportedTensorTypeError(item)
    else:
        raise InvalidKeyTypeError(item)

def open_switcher(self, symbol=False):
    switcher = self.switcher
    if switcher is not None and switcher.isVisible():
        switcher.clear()
        switcher.hide()
        return
    if symbol:
        switcher.set_search_text('@')
    else:
        switcher.set_search_text('')
        switcher.setup()
    mainwindow = self._plugin.get_main()
    default_top = mainwindow.toolbar.toolbars_menu.geometry().height() + mainwindow.menuBar().geometry().height() + 8
    current_window = QApplication.activeWindow()
    if current_window == mainwindow:
        if self.get_conf('toolbars_visible', section='toolbar'):
            delta_top = default_top
        else:
            delta_top = mainwindow.menuBar().geometry().height() + 8
    else:
        delta_top = default_top
    switcher.set_position(delta_top, current_window)
    switcher.show()

