    txtorlog.msg('connection terminated: ' + str(reason))
    if reason.check(ConnectionDone):
        self._when_disconnected.fire(self)
    else:
        self._when_disconnected.fire(reason)
    if self.on_disconnect and (not self.on_disconnect.called) and self.on_disconnect.callbacks:
        warn('TorControlProtocol.on_disconnect is deprecated; use .when_disconnected() instead', DeprecationWarning)
        if reason.check(ConnectionDone):
            self.on_disconnect.callback(self)
        else:
            self.on_disconnect.errback(reason)
    self.on_disconnect = None
    self._when_disconnected.fire(self)
    outstanding = [self.command] + self.commands if self.command else self.commands
    for (d, cmd, cmd_arg) in outstanding:
        if not d.called:
            d.errback(Failure(TorDisconnectError(text='Tor unexpectedly disconnected while running: {}'.format(cmd.decode('ascii')), error=reason)))
    return None

def student_editable(self):
    if self.activity.due_date and self.activity.due_date < datetime.datetime.now():
        return 'due date has passed'
    if isinstance(self.activity, LetterActivity):
        GradeClass = LetterGrade
    else:
        GradeClass = NumericGrade
    grades = GradeClass.objects.filter(activity=self.activity, member=self.student).exclude(flag='NOGR')
    if len(grades) > 0:
        return 'grade already received for activity'
    subs = GroupSubmission.objects.filter(group=self.group, activity=self.activity)
    if len(subs) > 0:
        return 'a submission has already been made for activity'
    return ''

