        queryset = Event.objects.all()
    else:
        queryset = Event.objects.filter(Q(is_submission=False), Q(is_published=True))
    q = self.request.query_params.get('q', None)
    pending = self.request.query_params.get('pending', None)
    if q:
        queryset = queryset.filter(Q(title__icontains=q) | Q(description__icontains=q) | Q(host__icontains=q) | Q(category__iexact=q))
    if pending:
        queryset = queryset.filter(is_submission=True)
    else:
        queryset = queryset.filter(is_submission=False)
    return queryset

