async def scala_bsp_dependency_modules(request: ScalaBSPDependencyModulesRequest, build_root: BuildRoot, classpath_entry_request: ClasspathEntryRequestFactory) -> BSPDependencyModulesResult:
    coarsened_targets = await Get(CoarsenedTargets, Addresses([fs.address for fs in request.field_sets]))
    resolve = await Get(CoursierResolveKey, CoarsenedTargets, coarsened_targets)
    lockfile = await Get(CoursierResolvedLockfile, CoursierResolveKey, resolve)
    applicable_lockfile_entries: dict[CoursierLockfileEntry, CoarsenedTarget] = {}
    for ct in coarsened_targets.coarsened_closure():
        for tgt in ct.members:
            if not JvmArtifactFieldSet.is_applicable(tgt):
                continue
            artifact_requirement = ArtifactRequirement.from_jvm_artifact_target(tgt)
            entry = get_entry_for_coord(lockfile, artifact_requirement.coordinate)
            if not entry:
                _logger.warning(f'No lockfile entry for {artifact_requirement.coordinate} in resolve {resolve.name}.')
                continue
            applicable_lockfile_entries[entry] = ct
    classpath_entries = await MultiGet((Get(ClasspathEntry, ClasspathEntryRequest, classpath_entry_request.for_targets(component=target, resolve=resolve)) for target in applicable_lockfile_entries.values()))
    resolve_digest = await Get(Digest, MergeDigests((cpe.digest for cpe in classpath_entries)))
    resolve_digest = await Get(Digest, AddPrefix(resolve_digest, f'jvm/resolves/{resolve.name}/lib'))
    modules = [DependencyModule(name=f'{entry.coord.group}:{entry.coord.artifact}', version=entry.coord.version, data=MavenDependencyModule(organization=entry.coord.group, name=entry.coord.artifact, version=entry.coord.version, scope=None, artifacts=tuple((MavenDependencyModuleArtifact(uri=build_root.pathlib_path.joinpath(f'.pants.d/bsp/jvm/resolves/{resolve.name}/lib/{filename}').as_uri()) for filename in cp_entry.filenames)))) for (entry, cp_entry) in zip(applicable_lockfile_entries, classpath_entries)]
    return BSPDependencyModulesResult(modules=tuple(modules), digest=resolve_digest)

