def visitMultiplyingExpression(self, ctx):
    left = float(self.visit(ctx.powExpression(0)))
    for i in range(len(ctx.operatorMulDiv())):
        right = float(self.visit(ctx.powExpression(i + 1)))
        if ctx.operatorMulDiv(i).TIMES():
            left *= right
        else:
            left /= right
    return left

