    if not sources:
        return None
    jdk = Distribution.cached(jdk=True)
    tool_classpath = jdk.find_libs(['tools.jar'])
    args = ['-quiet', '-encoding', 'UTF-8', '-notimestamp', '-use', '-classpath', ':'.join(classpath), '-d', gendir]
