        for jar in target.jar_dependencies:
            if jar.apidocs:
                offlinelinks.add(jar.apidocs)
    for target in targets:
        target.walk(link, lambda t: t.is_jvm)
    for link in offlinelinks:
        args.extend(['-linkoffline', link, link])
    args.extend(self.args)
