        fine_grained_views = (self._apply_operation_on_fine_grained_view(operation_def, upstream_view.fine_grained_view, next_hashed_path),)
    else:
        fine_grained_views = (None,) * operation_def.num_outputs
    flattened_views = nodes.OperationNode(operation_def, (upstream_view.flattened_view,)).outputs
    assert len(fine_grained_views) == len(flattened_views)
    return tuple((_OptimizationView(prefer_fine_grained_view=prefer_fine_grained_view, flattened_view=flat, fine_grained_view=fine, hashed_path=next_hashed_path) for (flat, fine) in zip(flattened_views, fine_grained_views)))

