def normalize_layers_pearson_residuals(adata: AnnData, layers: list=['X'], select_genes_layer='X', select_genes_key='use_for_pca', copy=False, **normalize_pearson_residual_args) -> None:
    if len(layers) == 0:
        main_warning('layers arg has zero length. return and do nothing in normalize_layers_pearson_residuals.')
    if not select_genes_layer in layers:
        main_warning('select_genes_layer: %s not in layers, using layer: %s instead to select genes instead.' % (select_genes_layer, layers[0]))
        select_genes_layer = layers[0]
    for layer in layers:
        temp_select_genes_key = None
        if select_genes_layer == layer:
            temp_select_genes_key = select_genes_key
        temp_adata = _normalize_single_layer_pearson_residuals(adata, layer=layer, var_select_genes_key=temp_select_genes_key, copy=copy, **normalize_pearson_residual_args)
        if layer != DKM.X_LAYER:
            new_X_key = DKM.gen_layer_X_key(layer)
            main_info_insert_adata_layer(new_X_key, indent_level=2)
            adata.layers[new_X_key] = DKM.select_layer_data(temp_adata, layer)

original_code:
def browser(request, percy, live_server):
    window_size = request.config.getoption('window_size')
    window_width, window_height = list(map(int, window_size.split('x', 1)))

    driver_type = request.config.getoption('selenium_driver')
    if driver_type == 'chrome':
        options = webdriver.ChromeOptions()
        options.add_argument('headless')
        options.add_argument('disable-gpu')
        options.add_argument('window-size={}'.format(window_size))
        chrome_path = request.config.getoption('chrome_path')
        if chrome_path:
            options.binary_location = chrome_path
        chromedriver_path = request.config.getoption('chromedriver_path')
        if chromedriver_path:
            driver = webdriver.Chrome(
                executable_path=chromedriver_path,
                chrome_options=options,
            )
        else:
            driver = webdriver.Chrome(
                chrome_options=options,
            )
    elif driver_type == 'firefox':
        driver = webdriver.Firefox()
    elif driver_type == 'phantomjs':
        phantomjs_path = request.config.getoption('phantomjs_path')
        if not phantomjs_path:
            phantomjs_path = os.path.join(
                'node_modules',
                'phantomjs-prebuilt',
                'bin',
                'phantomjs',
            )
        driver = webdriver.PhantomJS(executable_path=phantomjs_path)
    else:
        raise pytest.UsageError('--driver must be specified')

    driver.set_window_size(window_width, window_height)

    def fin():
        # Teardown Selenium.
        try:
            driver.close()
        except Exception:
            pass
        # TODO: remove this when fixed in: https://github.com/seleniumhq/selenium/issues/767
        if hasattr(driver, 'service'):
            driver.service.process.send_signal(signal.SIGTERM)
        driver.quit()

    request.node._driver = driver
    request.addfinalizer(fin)

    browser = Browser(driver, live_server, percy)

    if hasattr(request, 'cls'):
        request.cls.browser = browser
    request.node.browser = browser

    # bind webdriver to percy for snapshots
    percy.loader.webdriver = driver

    return driver

