def windowize_function(expr, default_frame):
    func = var('func')
    frame = var('frame')
    wrap_analytic = (p.Analytic | p.Reduction) >> c.WindowFunction(_, default_frame)
    merge_frames = p.WindowFunction(func, frame) >> c.WindowFunction(func, frame.copy(order_by=frame.order_by + default_frame.order_by, group_by=frame.group_by + default_frame.group_by))
    node = expr.op()
    node = node.replace(merge_frames, filter=p.Value)
    node = node.replace(wrap_analytic, filter=p.Value & ~p.WindowFunction)
    return node.to_expr()

def create(self, trans, visualization_title='', visualization_slug='', visualization_annotation='', visualization_dbkey='', visualization_type=''):
    visualization_title_err = visualization_slug_err = visualization_annotation_err = ''
    if trans.request.method == 'POST':
        rval = self.create_visualization(trans, title=visualization_title, slug=visualization_slug, annotation=visualization_annotation, dbkey=visualization_dbkey, type=visualization_type)
        if isinstance(rval, dict):
            visualization_title_err = rval['title_err']
            visualization_slug_err = rval['slug_err']
        else:
            return trans.response.send_redirect(web.url_for(action='list'))
    viz_type_options = [(t, t) for t in self.viz_types]
