def restraints_residual_sum(self, sites_cart, gradient_array=None):
    if gradient_array is None:
        gradient_array = flex.vec3_double(sites_cart.size(), (0.0, 0.0, 0.0))
    target = 0
    if self.ramachandran_proxies is not None:
        target += self.ramachandran_lookup.restraints_residual_sum(sites_cart=sites_cart, proxies=self.ramachandran_proxies, gradient_array=gradient_array)
    if self.hydrogen_bond_proxies is not None:
        target += hbond.target_and_gradients(proxies=self.hydrogen_bond_proxies, sites_cart=sites_cart, gradient_array=gradient_array, falloff_distance=self.hydrogen_bond_params.falloff_distance)
    return target

