def run_command(self, command, cwd=None, user_input=None, ignore_errors=False):
    if cwd is None:
        cwd = os.path.join(self.tempdir, 'superlists')
    if command == 'wget -O bootstrap.zip https://github.com/twbs/bootstrap/archive/v3.0.0.zip':
        shutil.copy(os.path.join(os.path.dirname(__file__), '../downloads/bootstrap-3.0.zip'), os.path.join(cwd, 'bootstrap.zip'))
        return
    actual_command = command
    if command.startswith('fab deploy'):
        actual_command = 'cd deploy_tools && ' + command
    process = subprocess.Popen(actual_command, shell=True, cwd=cwd, executable='/bin/bash', stdout=subprocess.PIPE, stderr=subprocess.STDOUT, stdin=subprocess.PIPE, preexec_fn=os.setsid, universal_newlines=True)
    process._command = command
    self.processes.append(process)
    if 'runserver' in command:
        return
    if user_input and (not user_input.endswith('\n')):
        user_input += '\n'
    (output, _) = process.communicate(user_input)
    if process.returncode and (not ignore_errors):
        if 'test' in command or 'diff' in command or 'migrate' in command:
            return output
        print('process %s return a non-zero code (%s)' % (command, process.returncode))
        print('output:\n', output)
        raise Exception('process %s return a non-zero code (%s)' % (command, process.returncode))
    print(output)
    return output

