    # TODO: legacy API, switch to use GATEWAY_LISTEN in the next step
    monkeypatch.setattr(config, "EDGE_PORT_HTTP", httpserver.port)
    monkeypatch.setattr(config, "EDGE_PORT", httpserver.port)

