def random_points(self, n, random='pseudo'):
    x = []
    while len(x) < n:
        tmp = np.random.rand(n, self.dim) * (self.bbox[1] - self.bbox[0]) + self.bbox[0]
        x += filter(self.inside, tmp)
    return np.array(x[:n])

processed_final_repaired_code:
def random_points(self, n, random='pseudo'):
    x = np.array([x for x in self.geom1.random_points(n, random=random) if not self.geom2.inside(x)])
    if len(x) < n:
        additional_points = self.geom2.random_points(n - len(x), random=random)
        x = np.vstack((x, additional_points))
    if n != len(x):
        print('Warning: {} points required, but {} points sampled. Uniform random is not guaranteed.'.format(n, len(x)))
    return x

