def get_price(self, to_asset: Asset, block_identifier: BlockIdentifier) -> Price:
    log.debug(f'Querying saddle for price of {from_asset} to {to_asset}')
    if from_asset != A_ALETH:
        raise PriceQueryUnsupportedAsset(f'{from_asset} is not a valid asset for the Saddle oracle')
    aleth_eth_price = SADDLE_ALETH_POOL.call(ethereum=self.eth_manager, method_name='calculateSwap', arguments=[1, 0, 1000000000000000000], block_identifier=block_identifier)
    aleth_eth_price /= EXP18
    if to_asset not in (A_WETH, A_ETH):
        eth_price = Inquirer().find_price(A_ETH, to_asset)
        return aleth_eth_price * eth_price
    return aleth_eth_price

def deserialize(dataone_exception_xml):
    error_str = None
    try:
        dataone_exception_pyxb = dataoneErrors.CreateFromDocument(dataone_exception_xml)
    except pyxb.ValidationError as e:
        error_str = e.details()
    except pyxb.PyXBException as e:
        error_str = e.message
    except xml.sax.SAXParseException as e:
        error_str = str(e)
    if error_str is not None:
        msg = StringIO.StringIO()
        msg.write('Deserialization failed.\n')
        msg.write('Error: {}\n'.format(error_str))
        msg.write('Input: {}\n'.format('<empty response>' if dataone_exception_xml == '' else dataone_exception_xml))
        raise ServiceFailure(detailCode=0, description=msg.getvalue(), traceInformation=traceback.format_exc())
        raise DataONEExceptionException(msg.getvalue())
    trace = getattr(dataone_exception_pyxb, 'traceInformation', None)
    return create_exception_by_name(dataone_exception_pyxb.name, dataone_exception_pyxb.detailCode, dataone_exception_pyxb.description, trace, dataone_exception_pyxb.identifier, dataone_exception_pyxb.nodeId)

