processed_manual_code:
def find_mount_point(directory):
    if isinstance(directory, bytes):
        raise ValueError('Convert bytes objects to str first.')
    if not isinstance(directory, str):
        raise ValueError('Directory names should be of type str.')
    directory = os.path.abspath(directory)
    while directory != '/':
        if os.path.ismount(directory):
            return directory
        else:
            (directory, tail_data) = os.path.split(directory)
    return '/'

def _ompize(self, state, **kwargs):
    processed = []
    for node in state.nodes:
        denormals = FindNodes(Denormals).visit(state.nodes)
        mapper = {i: List(c.Comment('DLE: moved denormals flag')) for i in denormals}
        for tree in retrieve_iteration_tree(node):
            key = lambda i: i.is_Parallel and (not i.is_Vectorizable)
            candidates = filter_iterations(tree, key=key, stop='consecutive')
            if not candidates:
                continue
            nparallel = len(candidates)
            if psutil.cpu_count(logical=False) < self.thresholds['collapse'] or nparallel < 2:
                parallelism = omplang['for']
            else:
                parallelism = omplang['collapse'](nparallel)
            root = candidates[0]
            mapper[root] = Block(header=omplang['par-region'], body=denormals + [Element(parallelism), root])
        processed.append(Transformer(mapper).visit(node))
    return {'nodes': processed}

