    if self.is_archived():
        raise RuntimeError('Unable to upload files to an archived sketch.')
    resource_url = f'{self.api.api_root}/upload/'
    files = {'file': open(file_path, 'rb')}
    (_, _, file_ending) = file_path.rpartition('.')
