        return None
    elif not isinstance(obj_weakref, weakref_ref):
        raise _BeartypeUtilPythonWeakrefException(f'Weak reference {repr(obj_weakref)} invalid (i.e., neither weak reference, "None", nor "_WEAKREF_NONE").')
    obj = obj_weakref()
    return obj if obj is not None else obj_repr

