def _init_keymanager(self, address, token):
    srp_auth = self.srpauth
    logger.debug('initializing keymanager...')
    if flags.OFFLINE is True:
        args = (address, 'https://localhost', self._soledad)
        kwargs = {'ca_cert_path': '', 'api_uri': '', 'api_version': '', 'uid': self._uuid, 'gpgbinary': self._get_gpg_bin_path()}
    else:
        args = (address, 'https://nicknym.%s:6425' % (self._provider_config.get_domain(),), self._soledad)
        kwargs = {'token': token, 'ca_cert_path': self._provider_config.get_ca_cert_path(), 'api_uri': self._provider_config.get_api_uri(), 'api_version': self._provider_config.get_api_version(), 'uid': srp_auth.get_uuid(), 'gpgbinary': self._get_gpg_bin_path()}
    try:
        self._keymanager = KeyManager(*args, **kwargs)
