        else:
            img = base_img.copy()
    if grayscale == True:
        img = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
    new_img = np.zeros((target_size[0], target_size[1], img.shape[2]), dtype=img.dtype)
    x_offset = (target_size[1] - img.shape[1]) // 2
    y_offset = (target_size[0] - img.shape[0]) // 2
    new_img[y_offset:y_offset + img.shape[0], x_offset:x_offset + img.shape[1]] = img
    img = new_img
    img_pixels = image.img_to_array(img)
    img_pixels = np.expand_dims(img_pixels, axis=0)
    img_pixels /= 255
    if return_region == True:
        return (img_pixels, region)
    else:
        return img_pixels

