    channel = self.channel
    logfile = getattr(config, '%s_logfile' % channel)
    maxbytes = getattr(config, '%s_logfile_maxbytes' % channel)
    backups = getattr(config, '%s_logfile_backups' % channel)
    to_syslog = getattr(config, '%s_syslog' % channel)
