def _is_name_used(self, check_name: str) -> int:
    if check_name in self._design.name_to_id:
        component_id = self._design.name_to_id[check_name]
        return component_id
    else:
        return 0

def close(self):
    with self._server.lock:
        for subs in self._server.subscribers.values():
            subs.discard(self)
        for subs in self._server.psubscribers.values():
            subs.discard(self)
        self._clear_watches()
    self._server = None
    self._db = None
    self.responses = None

