def create_default_callbacks(callbacks: Optional[List[Callback]], sync_config: SyncConfig, loggers: Optional[List[Logger]], metric: Optional[str]=None):
    callbacks = callbacks or []
    has_syncer_callback = False
    has_csv_logger = False
    has_json_logger = False
    has_tbx_logger = False
    has_trial_progress_callback = any((isinstance(c, TrialProgressCallback) for c in callbacks))
    if not has_trial_progress_callback:
        trial_progress_callback = TrialProgressCallback(metric=metric)
        callbacks.append(trial_progress_callback)
    last_logger_index = None
    syncer_index = None
    if loggers:
        add_loggers = []
        for trial_logger in loggers:
            if isinstance(trial_logger, LoggerCallback):
                callbacks.append(trial_logger)
            elif isinstance(trial_logger, type) and issubclass(trial_logger, Logger):
                add_loggers.append(trial_logger)
            else:
                raise ValueError(f'Invalid value passed to `loggers` argument of `tune.run()`: {trial_logger}')
        if add_loggers:
            callbacks.append(LegacyLoggerCallback(add_loggers))
    for (i, callback) in enumerate(callbacks):
        if isinstance(callback, LegacyLoggerCallback):
            last_logger_index = i
            if CSVLogger in callback.logger_classes:
                has_csv_logger = True
            if JsonLogger in callback.logger_classes:
                has_json_logger = True
            if TBXLogger in callback.logger_classes:
                has_tbx_logger = True
        elif isinstance(callback, CSVLoggerCallback):
            has_csv_logger = True
            last_logger_index = i
        elif isinstance(callback, JsonLoggerCallback):
            has_json_logger = True
            last_logger_index = i
        elif isinstance(callback, TBXLoggerCallback):
            has_tbx_logger = True
            last_logger_index = i
        elif isinstance(callback, SyncerCallback):
            syncer_index = i
            has_syncer_callback = True
    if os.environ.get('TUNE_DISABLE_AUTO_CALLBACK_LOGGERS', '0') != '1':
        if not has_csv_logger:
            callbacks.append(CSVLoggerCallback())
            last_logger_index = len(callbacks) - 1
        if not has_json_logger:
            callbacks.append(JsonLoggerCallback())
            last_logger_index = len(callbacks) - 1
        if not has_tbx_logger:
            try:
                callbacks.append(TBXLoggerCallback())
                last_logger_index = len(callbacks) - 1
            except ImportError:
                logger.warning("The TensorboardX logger cannot be instantiated because either TensorboardX or one of it's dependencies is not installed. Please make sure you have the latest version of TensorboardX installed: `pip install -U tensorboardx`")
    if not has_syncer_callback and os.environ.get('TUNE_DISABLE_AUTO_CALLBACK_SYNCER', '0') != '1':
        _cluster_syncer = detect_cluster_syncer(sync_config)
        syncer_callback = SyncerCallback(sync_function=_cluster_syncer)
        callbacks.append(syncer_callback)
        syncer_index = len(callbacks) - 1
    if syncer_index is not None and last_logger_index is not None and (syncer_index < last_logger_index):
        if (not has_csv_logger or not has_json_logger or (not has_tbx_logger)) and (not loggers):
            raise ValueError('The `SyncerCallback` you passed to `tune.run()` came before at least one `LoggerCallback`. Syncing should be done after writing logs. Please re-order the callbacks so that the `SyncerCallback` comes after any `LoggerCallback`.')
        else:
            syncer_obj = callbacks[syncer_index]
            callbacks.pop(syncer_index)
            callbacks.insert(last_logger_index, syncer_obj)
    return callbacks

