def _filter_search(request, qs, data, region=None, profile=None):
    order_by = []
    if data.get('q'):
        qs = qs.query('function_score', query=name_query(data['q'].lower()), functions=[query.SF('field_value_factor', field='boost')])
    else:
        order_by = ['-popularity']
    form_to_es = {'cat': 'category', 'tag': 'tags', 'device': 'device', 'premium_types': 'premium_type', 'app_type': 'app_type', 'manifest_url': 'manifest_url', 'languages': 'supported_locales'}
    terms_fields = ('category', 'premium_type', 'app_type', 'supported_locales')
    for (k, field) in form_to_es.items():
        value = data.get(k)
        if value:
            filter_type = 'terms' if field in terms_fields else 'term'
            qs = qs.filter(filter_type, **{field: value})
    if data.get('offline') in (True, False):
        qs = qs.filter('term', is_offline=data['offline'])
    if profile:
        for (k, v) in profile.to_kwargs(prefix='features.has_').items():
            qs = qs.filter('term', **{k: v})
    if data.get('sort'):
        if 'popularity' in data['sort'] and region and (not region.adolescent):
            order_by = ['-popularity_%s' % region.id]
        else:
            order_by = [DEFAULT_SORTING[name] for name in data['sort'] if name in DEFAULT_SORTING]
    if order_by:
        qs = qs.sort(*order_by)
    return qs

