def _projection(self, widget=None):
    models = self._get_projectable_models()
    if not models:
        return
    self.core.get('update_progress')('Calculating 2D projection')
    total_models = len(models)
    for (index, model) in enumerate(models):
        progress = (index + 1) / total_models * 100
        self.core.get('update_progress')(f'Calculating 2D projection: {progress:.2f}% complete')
        for (objname, z_level) in (('ProjectionModelTop', model.maxz), ('ProjectionModelMiddle', (model.minz + model.maxz) / 2.0), ('ProjectionModelBottom', model.minz), ('ProjectionModelCustom', self.gui.get_object('ProjectionZLevel').get_value())):
            if self.gui.get_object(objname).get_active():
