def get_summary(self, use_summary_made=False):
    cell = self.data
    warnings.warn('get_summary is deprecated. Use the CellpyCell.data.summary property instead.', DeprecationWarning)
    if use_summary_made:
        summary_made = cell.has_summary
    else:
        summary_made = True
    if not summary_made:
        warnings.warn('Summary is not made yet')
        return None
    else:
        logging.info('Returning datasets[test_no].summary')
        return cell.summary

