def add_model_components(m, d):
    m.Overgeneration_MW = Var(m.LOAD_ZONES, m.TIMEPOINTS, within=NonNegativeReals)
    m.Unserved_Energy_MW = Var(m.LOAD_ZONES, m.TIMEPOINTS, within=NonNegativeReals)

    def overgeneration_expression_rule(mod, z, tmp):
        return mod.allow_overgeneration[z] * mod.Overgeneration_MW[z, tmp]
    m.Overgeneration_MW_Expression = Expression(m.LOAD_ZONES, m.TIMEPOINTS, rule=overgeneration_expression_rule)

    def unserved_energy_expression_rule(mod, z, tmp):
        return mod.allow_unserved_energy[z] * mod.Unserved_Energy_MW[z, tmp]
    m.Unserved_Energy_MW_Expression = Expression(m.LOAD_ZONES, m.TIMEPOINTS, rule=unserved_energy_expression_rule)
    getattr(d, load_balance_production_components).append('Unserved_Energy_MW_Expression')
    getattr(d, load_balance_consumption_components).append('Overgeneration_MW_Expression')

    def meet_load_rule(mod, z, tmp):
        return sum((getattr(mod, component)[z, tmp] for component in getattr(d, load_balance_production_components))) == sum((getattr(mod, component)[z, tmp] for component in getattr(d, load_balance_consumption_components)))
    m.Meet_Load_Constraint = Constraint(m.LOAD_ZONES, m.TIMEPOINTS, rule=meet_load_rule)

def get_argument_parser(self):
    metadata = self._get_action_metadata()
    parameters = metadata['parameters']
    required_parameters = metadata.get('required_parameters', [])
    parser = argparse.ArgumentParser(description='')
    for (parameter_name, parameter_options) in parameters.items():
        name = parameter_name.replace('_', '-')
        description = parameter_options['description']
        _type = parameter_options['type']
        required = parameter_name in required_parameters
        default_value = parameter_options.get('default', None)
        immutable = parameter_options.get('immutable', False)
        if immutable:
            continue
        args = ['--%s' % name]
        kwargs = {'help': description, 'required': required}
        if default_value is not None:
            kwargs['default'] = default_value
        if _type == 'string':
            kwargs['type'] = str
        elif _type == 'integer':
            kwargs['type'] = int
        elif _type == 'boolean':
            if default_value is False:
                kwargs['action'] = 'store_false'
            else:
                kwargs['action'] = 'store_true'
        parser.add_argument(*args, **kwargs)
    return parser

