def _get_num_gpus(ray_start_params: Dict[str, str], k8s_resource_limits: Dict[str, Any], group_name: str) -> Optional[int]:
    if 'num-gpus' in ray_start_params:
        return int(ray_start_params['num-gpus'])
    else:
        for key in k8s_resource_limits:
            if key.endswith('gpu'):
                gpu_resource_quantity = k8s_resource_limits[key]
                num_gpus = _round_up_k8s_quantity(gpu_resource_quantity)
                if num_gpus > 0:
                    return num_gpus
    return None

original_code:
def state_check(self):
    ps = self._printer.get_stat("print_stats")
    if ps['state'] == self.state:
        return True
    _ = self.lang.gettext

    if ps['state'] == "printing":
        if self.state == "cancelling":
            return True
        self.set_state("printing")
    elif ps['state'] == "complete":
        self.progress = 1
        self.update_progress()
        self.set_state("complete")
        self._screen.wake_screen()
        timeout = self._config.get_main_config().getint("job_complete_timeout", 30)
        if timeout != 0:
            self.close_timeouts.append(GLib.timeout_add_seconds(timeout, self.close_panel))
        return False
    elif ps['state'] == "error":
        logging.debug("Error!")
        self.set_state("error")
        self.labels['status'].set_text("%s - %s" % (_("Error"), ps['message']))
        self._screen.wake_screen()
        timeout = self._config.get_main_config().getint("job_error_timeout", 0)
        if timeout != 0:
            self.close_timeouts.append(GLib.timeout_add_seconds(timeout, self.close_panel))
        return False
    elif ps['state'] == "cancelled" or ps['state'] == "standby":
        # Print was cancelled
        self.set_state("cancelled")
        self._screen.wake_screen()
        timeout = self._config.get_main_config().getint("job_cancelled_timeout", 0)
        if timeout != 0:
            self.close_timeouts.append(GLib.timeout_add_seconds(timeout, self.close_panel))
        return False
    elif ps['state'] == "paused":
        self.set_state("paused")

    # TODO: Remove this in the future
    if self.filename != ps['filename']:
        if ps['filename'] != "":
            self.filename = ps['filename']
            self.file_metadata = {}
            self.update_text("file", self.filename.split("/")[-1])
        else:
            file = "Unknown"
            self.update_text("file", "Unknown file")

    return True

def vote():
    annotator = get_current_annotator()
    if annotator.prev.id == int(request.form['prev_id']) and annotator.next.id == int(request.form['next_id']):
        if request.form['action'] == 'Skip':
            annotator.ignore.append(annotator.next)
        elif request.form['action'] == "SkipNotHere":
            # TODO: Flag team if above passed
            annotator.ignore.append(annotator.next)
        else:
            # ignore things that were deactivated in the middle of judging
            if annotator.prev.active and annotator.next.active:
                if request.form['action'] == 'Previous':
                    perform_vote(annotator, next_won=False)
                    decision = Decision(annotator, winner=annotator.prev, loser=annotator.next)
                    print("Triggered Previous")
                elif request.form['action'] == 'Current':
                    perform_vote(annotator, next_won=True)
                    decision = Decision(annotator, winner=annotator.next, loser=annotator.prev)
                    print("Triggered Current")
                else:
                    return
                db.session.add(decision)
            annotator.next.viewed.append(annotator) # counted as viewed even if deactivated
            annotator.prev = annotator.next
            annotator.ignore.append(annotator.prev)
        annotator.update_next(choose_next(annotator))
        db.session.commit()
    return redirect(url_for('index'))

