        try:
            assign = int(request.args.get('assign', 1))
        except ValueError:
            abort(400)
        if assign:
            a = Action(t.id, 'assigned', osmid)
            t.current_state = a
            db.session.add(a)
            db.session.add(t)
        d = {'id': t.identifier, 'center': t.location, 'features': t.manifest}
        if t.instructions:
            d['instructions'] = t.instructions
        return jsonify(d)
    elif request.method == 'POST':
        valid_actions = [i.action for i in c.dlg['buttons']]
        a = None
        for k in valid_actions:
            if request.form.get(k):
                a = Action(t.id, k, osmid)
                t.current_action = a
                db.session.add(a)
                break
        if not a:
            return abort(400, description='Invalid action')
        new_state = c.task_status(t)
        a = Action(t.id, new_state, osmid)
        t.current_action = a
        db.session.add(a)
        db.session.add(t)
        db.commit()

