def _get_mappings(self, account, password, tpl):
    if tpl['type'] == 'letter' and account.owner_type != self.const.entity_person:
        raise CerebrumError('Cannot make letter to non-personal account {}'.format(account.account_name))
    mappings = mappers.get_account_mappings(account, password)
    if account.owner_type == self.const.entity_group:
        mappings.update(self._get_group_account_mappings(account))
    elif account.owner_type == self.const.entity_person:
        mappings.update(self._get_person_account_mappings(account, tpl['type']))
    else:
        raise CerebrumError('Unsupported account owner type %s'.format(account.owner_type))
    return mappings

round_1_repaired_code:
def _get_mappings(self, account, tpl):
    mapping = dict()
    if account.owner_type == self.const.entity_group:
        group = self._get_group(account.owner_id, idtype='id')
        mapping['group'] = group.group_name
    elif account.owner_type == self.const.entity_person:
        person = self._get_person('id', account.owner_id)
        mapping['fullname'] = person.get_name(self.const.system_cached, self.const.name_full)
    else:
        raise CerebrumError('Unsupported account owner type %s' % account.owner_type)
    if tpl.get('lang', '').endswith('letter'):
        if account.owner_type != self.const.entity_person:
            raise CerebrumError('Cannot make letter to non-personal account %s ' % account.account_name)
        mapping['barcode'] = 'barcode_%s.eps' % account.entity_id
        address = None
        for (source, kind) in ((self.const.system_sap, self.const.address_post), (self.const.system_fs, self.const.address_post), (self.const.system_sap, self.const.address_post_private), (self.const.system_fs, self.const.address_post_private)):
            address = person.get_entity_address(source=source, type=kind)
            if address:
                break
        if not address:
            raise CerebrumError("Couldn't get authoritative address for %s" % account.account_name)
        address = address[0]
        alines = address['address_text'].split('\n') + ['']
        mapping['address_line1'] = mapping['fullname']
        if alines:
            mapping['address_line2'] = alines[0]
            mapping['address_line3'] = alines[1]
        else:
            mapping['address_line2'] = ''
            mapping['address_line3'] = ''
        mapping['zip'] = address['postal_number']
        mapping['city'] = address['city']
        mapping['country'] = address['country']
        mapping['birthdate'] = person.birth_date.strftime('%Y-%m-%d')

    def unicodify(value):
        if isinstance(value, str):
            try:
                value = value.decode('UTF-8')
            except UnicodeDecodeError:
                value = value.decode('ISO-8859-1')
        return value
    for (k, v) in mapping.items():
        if not v:
            continue
        mapping[k] = unicodify(v).encode('UTF-8')
    return mapping

