def learn_host_on_vlan_ports(self, port, vlan, eth_src, delete_existing=True):
    now = time.time()
    ofmsgs = []
    ban_age = None
    learn_ban = False
    if port.loop_protect:
        if port.dyn_last_ban_time:
            ban_age = now - port.dyn_last_ban_time
        if ban_age and ban_age < 2:
            learn_ban = True
    if not learn_ban:
        entry = vlan.cached_host(eth_src)
        if entry is not None:
            cache_age = now - entry.cache_time
            if cache_age < 2:
                if entry.port == port:
                    return ofmsgs
                elif port.loop_protect:
                    if ban_age is None or ban_age > 2:
                        learn_ban = True
                        port.dyn_learn_ban_count += 1
                        ofmsgs.append(self._temp_ban_host_learning_on_port(port))
                        self.logger.info('rapid move of %s from %s to %s, temp loop ban %s' % (eth_src, entry.port, port, port))
                    elif ban_age < 2:
                        learn_ban = True
    if learn_ban:
        port.dyn_last_ban_time = now
        return ofmsgs
    (src_rule_idle_timeout, src_rule_hard_timeout, dst_rule_idle_timeout) = self.learn_host_timeouts(port)
    ofmsgs.extend(self.learn_host_on_vlan_port_flows(port, vlan, eth_src, delete_existing, src_rule_idle_timeout, src_rule_hard_timeout, dst_rule_idle_timeout))
    vlan.add_cache_host(eth_src, port, now)
    self.logger.info('learned %s on %s on VLAN %u (%u hosts total)' % (eth_src, port, vlan.vid, vlan.hosts_count()))
    return ofmsgs
